#!/usr/bin/env bash
#
# The old-to-new path of an Alchemy or Effect move: a disposable content Site
# generated by an earlier @getquick/site release from npm (0.40.0 by default,
# the last on Alchemy 2.0.0-beta.79 and Effect 4.0.0-rc.115, the fleet's
# catalog before the package split), Astro and TanStack, installed as that
# release left it, then updated to this checkout the way a
# Site's update PR does it:
#
# 1. @getquick/site bumped to this checkout's version and installed from it
#    (this-checkout.sh);
# 2. `gq sync`, which must move both halves at once: the managed infra/*.ts
#    onto @alchemy.run/cloudflare, infra/package.json depending on it, and
#    pnpm-workspace.yaml's managed catalog keys onto this checkout's pins
#    (blueprint/templates/fragments/pnpm-workspace.keys.yaml), with every
#    other byte of that file kept;
# 3. `pnpm install` regenerates the lock, `pnpm install --frozen-lockfile`
#    passes against it, and `gq sync --check` passes;
# 4. `pnpm infra:check` and `pnpm ci:check` type-check the managed infra
#    against the installed packages, and `gq doctor` passes, its Alchemy
#    check included.
#
# GQ_SYNC_FROM picks the earlier release. Generation and gq sync stay
# offline and secret-free; npx and pnpm install use the network. Nothing is
# provisioned or deployed. The Sites are deleted afterwards unless KEEP=1.

set -euo pipefail

repo=$(cd "$(dirname "$0")/../.." && pwd)
source "$repo/scripts/smoke/this-checkout.sh"
from=${GQ_SYNC_FROM:-0.40.0}
parent=$(mktemp -d "${TMPDIR:-/tmp}/gq-sync-upgrade.XXXXXX")
if [[ "${KEEP:-}" == 1 ]]; then
  echo "Keeping the sites in $parent"
else
  trap 'rm -rf "$parent"' EXIT
fi

fail() {
  echo "✗ $*" >&2
  exit 1
}

# Each managed key of pnpm-workspace.yaml at this checkout's pin (`moved`),
# or none of them there yet (`old`).
workspace_pins() {
  node --input-type=module -e '
    import { readFileSync } from "node:fs";
    import { createRequire } from "node:module";
    const [repo, expect] = process.argv.slice(1);
    const { parse } = createRequire(`${repo}/package.json`)("yaml");
    const pins = parse(readFileSync(`${repo}/blueprint/templates/fragments/pnpm-workspace.keys.yaml`, "utf8"));
    const site = parse(readFileSync("pnpm-workspace.yaml", "utf8"));
    const leaves = (object, path = []) => Object.entries(object).flatMap(([key, value]) =>
      value && typeof value === "object" ? leaves(value, [...path, key]) : [[[...path, key], value]]);
    const at = (path) => path.reduce((node, key) => node?.[key], site);
    const differ = leaves(pins).filter(([path, value]) => at(path) !== value);
    for (const [path, value] of leaves(pins)) console.log(`  ${path.join(" ")}: ${at(path)}`);
    if (expect === "moved" && differ.length > 0) {
      throw new Error(`pnpm-workspace.yaml is not at the pins: ${differ.map(([path]) => path.join(" ")).join(", ")}`);
    }
    if (expect === "old" && differ.length === 0) throw new Error("the Site already has the new pins");
  ' "$repo" "$1"
}

for framework in astro tanstack; do
  project="orbit-$framework"
  site="$parent/$project"
  echo "== $project: generated by @getquick/site $from"
  cd "$parent"
  npx -y "@getquick/site@$from" new "$project" --project "$project" --variant content \
    --framework "$framework" </dev/null >/dev/null
  cd "$site"
  workspace_pins old
  # The Site as the earlier release left it, installed.
  CI=1 pnpm install --no-frozen-lockfile >/dev/null
  cp pnpm-workspace.yaml "$parent/$project.workspace.yaml"

  echo "== $project: updated to this checkout"
  use_this_checkout "$repo" "$site"
  node -e '
    const fs = require("node:fs");
    const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
    pkg.devDependencies["@getquick/site"] = require(process.argv[1]).version;
    fs.writeFileSync("package.json", JSON.stringify(pkg, null, 2) + "\n");
  ' "$repo/package.json"
  CI=1 pnpm install --no-frozen-lockfile >/dev/null
  pnpm exec gq sync

  # Both halves moved.
  grep -q 'from "@alchemy.run/cloudflare"' infra/frontend.run.ts || fail "frontend.run.ts"
  grep -q 'from "@alchemy.run/cloudflare"' infra/consent.ts || fail "consent.ts"
  if grep -rn 'alchemy/Cloudflare' infra --include='*.ts' --exclude-dir=node_modules; then
    fail "the managed infra still imports alchemy/Cloudflare"
  fi
  node -e '
    const deps = require("./infra/package.json").dependencies;
    if (deps["@alchemy.run/cloudflare"] !== "catalog:") throw new Error("infra/package.json");
  '
  workspace_pins moved
  # Only managed keys changed, apart from the this-checkout override: every
  # changed line is an Alchemy or Effect pin.
  if diff -U0 "$parent/$project.workspace.yaml" pnpm-workspace.yaml | grep '^[-+] ' |
    grep -vE '^[-+] +("@alchemy\.run/[a-z-]+"|"@effect/platform-node(-shared)?"|alchemy|effect): ' |
    grep -v '"@getquick/site": "file:'; then
    fail "gq sync changed a pnpm-workspace.yaml line it doesn't manage"
  fi

  # The lock follows the catalog, then holds. (pnpm exec, in CI, first checks
  # the install against the lock, so nothing runs through it until then.)
  CI=1 pnpm install --no-frozen-lockfile >/dev/null
  CI=1 pnpm install --frozen-lockfile >/dev/null
  pnpm exec gq sync --check >/dev/null
  pnpm infra:check
  pnpm ci:check
  pnpm exec gq doctor
  echo "✓ $project: synced from $from, installed, type-checked and doctor-clean"
done
